'use strict';

// MODULES //

var path = require( 'node:path' );
var readdir = require( 'node:fs/promises' ).readdir;
var parseRecordPath = require( '@data-apis/record/parse-path' );


// MAIN //

/**
* Lists and validates record paths in a data directory.
*
* @param {string} dataDirectory - data directory
* @returns {Promise<Array>} sorted relative paths
*/
async function walkRecordPaths( dataDirectory ) {
	var found = [];
	var libraryEntry;
	var sourceEntry;
	var recordEntry;
	var relative;
	var libraries;

	try {
		libraries = await readdir( dataDirectory, { 'withFileTypes': true } );
	} catch ( error ) {
		if ( error.code === 'ENOENT' ) {
			return [];
		}
		throw error;
	}
	for ( libraryEntry of libraries ) {
		if ( libraryEntry.name === 'index.json' ) {
			continue;
		}
		if ( !libraryEntry.isDirectory() ) {
			throw new Error( 'Unexpected file in data directory: ' + libraryEntry.name );
		}
		for ( sourceEntry of await readdir( path.join( dataDirectory, libraryEntry.name ), { 'withFileTypes': true } ) ) {
			if ( !sourceEntry.isDirectory() ) {
				throw new Error( 'Unexpected file in library data directory: ' + libraryEntry.name + '/' + sourceEntry.name );
			}
			for ( recordEntry of await readdir( path.join( dataDirectory, libraryEntry.name, sourceEntry.name ), { 'withFileTypes': true } ) ) {
				if ( !recordEntry.isFile() ) {
					throw new Error( 'Unexpected nested directory in data: ' + libraryEntry.name + '/' + sourceEntry.name + '/' + recordEntry.name );
				}
				relative = libraryEntry.name + '/' + sourceEntry.name + '/' + recordEntry.name;
				parseRecordPath( relative );
				found.push( relative );
			}
		}
	}
	return found.sort();
}


// EXPORTS //

module.exports = walkRecordPaths;
